-- GENERATED by `wfj generate` from data/gossip/gossip-ac.jsonl. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("gossip", {
  ["ac01be218f4d0d48"] = { "Be', per me si torna al lavoro. Però è stato proprio bello fare quella breve pausa, ed è sempre bello bere ⟦Thunder Ale=Birra del Tuono⟧!", "." },
  ["ac0643cfc349b368"] = { "Aprilo, e stavolta fai attenzione!", "." },
  ["ac0ad82c963727a1"] = { "Che la tua anima bruci nell'angoscia, Isillien! Luce, dammi la forza di combattere questo demonio.", "." },
  ["ac1c2d654bc5fb2c"] = { "Hai fatto un buon lavoro, {name}. Credo che tu sia <pronto/pronta> per il prossimo compito.", "." },
  ["ac2bee11166998d3"] = { "Mettiti in viaggio verso Orgrimmar e cercalo nella ⟦Valley of Honor=Valle dell'Onore⟧. Lavora in una bottega chiamata Arms of Legend.", "." },
  ["ac2d162b5b23d790"] = { "Lady Sylvanas ha ordinato di studiare alcuni fenomeni naturali di Azeroth. Ritiene che ci sia qualcosa di grande da imparare dal suo passato segreto.\n\nNon so come abbia appreso queste cose, ma mi fido ciecamente di lei, quindi farò del mio meglio.\n\nAl momento sto studiando le melme, i liquami e simili. Le creature sembrano tutte simili nella composizione, ma fortemente influenzate dal loro ambiente.\n\nMi farebbe comodo il tuo aiuto per raccogliere campioni di queste creature..", "." },
  ["ac2f4ddb6037e7f2"] = { "Cosa? Come osi dirmi una cosa del genere?!?", "." },
  ["ac2fc424b7ef0624"] = { "Cosa cosa?!? Abbiamo tutti dei profitti da fare... e non li faremo stando con le mani in mano.", "." },
  ["ac32b440a8c6c0c9"] = { "Esaminando più da vicino il pilastro, trovi un piccolo tavolo con cristalli rossi, blu e verdi disposti in quella che sembra una formazione precisa.\n\nUn grande cerchio di cristalli rossi è affiancato da un lato da un cerchio più piccolo di cristalli blu e dall'altro da uno di cristalli verdi.\n\nPrendi nota con attenzione dei colori dei cristalli, sapendo che J.D. sarebbe molto interessato a sapere cosa hai trovato.", "." },
  ["ac37d32506e36c3a"] = { "Unità Alarm-a-bomb 2600 guasta. Esclusione autodistruzione [ATTIVA]. Raffreddamento [ATTIVO].", "." },
  ["ac3d3a33fedd2add"] = { "Buongiorno, amici miei.", "." },
  ["ac3f67a3303b3d66"] = { "Ho bisogno di addestramento, Arnok.", "." },
  ["ac42f9ab3d424042"] = { "Parlami della capitana Balinda Cordipietra.", "." },
  ["ac45802536c66428"] = { "Sia motivo d'orgoglio per te, {class}, il fatto che l'⟦Alliance=Alleanza⟧ abbia completato tutti i compiti di raccolta che le erano stati assegnati. I prodotti finiti sono immagazzinati e conservati, e i nostri esperti di professioni stanno lavorando sodo per trasformare quelle materie prime in materiale bellico da spedire a ⟦Silithus=Silitus⟧ non appena l'⟦Horde=Orda⟧ finirà le sue raccolte.", "." },
  ["ac46be328eb0b910"] = { "Il tuo talento eccelle! Hai davvero ispirazione. Per proseguire la tua ricerca della conoscenza, parla con Georgio Bolero a ⟦Stormwind=Roccavento⟧. È tenuto in grande considerazione e potrà continuare il tuo addestramento.", "." },
  ["ac4ba00ab0e6f25b"] = { "L'anziano Malatomba passa il suo tempo vicino a Brill, nelle ⟦Tirisfal Glades=Radure di Tirisfal⟧.", "." },
  ["ac51bc16096c47d1"] = { "È al Godan's Runeworks che devi andare. Lo trovi all'estremità ovest del Varcolargo, proprio accanto alla Valle della Saggezza.", "." },
  ["ac5271e8915937cc"] = { "Costrizioni? Ci sono cose in questo mondo ben più costrittive di sbarre e catene, <signorino/signorina>. I non morti ci circondavano, tormentandoci di continuo con orribili atti di depravazione.\n\nAlla fine arrivò lui. Si presentò come il dottor Theolen Krastinov. Noi imparammo a conoscerlo come «il ⟦The Butcher=Macellaio⟧».", "." },
  ["ac538cde8f753f24"] = { "Sempre vigili nella protezione del mondo naturale, i Druidi sono guidati dall'arcidruido Fandral Elmocervo, che risiede nell'⟦Cenarion Enclave=Enclave Cenariana⟧. Troverai lui e gli altri istruttori dei Druidi nella parte settentrionale di Darnassus.", "." },
  ["ac5e6ae1533fd966"] = { "Il drago si nasconde dietro una facciata regale. Le tavolette mostreranno ciò che è davvero... Se ciò che ho visto è vero, non sopravvivrò a questa battaglia, amico. Sei tu che devi finire ciò che ho iniziato. Le tue forze sono pronte? Tu sei <pronto/pronta>? Cominceremo al tuo comando.", "." },
  ["ac6b95958208758a"] = { "Dov'è l'istruttore di Erbalismo?", "." },
  ["ac76e7594cc2dbfa"] = { "Forse vorrai raccontarmi le tue gesta, {name}. Sarebbe un onore conoscerle.", "." },
  ["ac774803dcfa7833"] = { "Spero sia qualcosa di serio, {class}. Fammi vedere cos'hai e raccontami la tua storia. Ma, per la Luce, sbrigati. La difesa di Borgoscuro è la mia priorità assoluta. Non ho tempo da sprecare dietro a piste senza uscita.", "." },
  ["ac8c7d3ad7a11a44"] = { "Spero un giorno di forgiare armi e armature con le ossa dei miei nemici.", "." },
  ["ac93a81c421407e5"] = { "<L'uomo disteso davanti a te si muove a disagio. Si sta riprendendo da ferite molto brutte.>", "." },
  ["ac99a1c7297d682e"] = { "Tu non prendere candela!", "." },
  ["ac9b1dd4bea697c7"] = { "La ⟦Scarlet Crusade=Crociata Scarlatta⟧ di ⟦Tyr's Hand=Mano di Tyr⟧, nelle ⟦Eastern Plaguelands=Terre Infette Orientali⟧, ha molti forzieri chiusi che metteranno alla prova la tua abilità.", "." },
  ["aca1ab3277aaf4c7"] = { "L'unica arma che conosco che non serve ad altro che a uccidere qualcuno. Non qualcosa, ma qualcuno. Queste lame sono state inventate per porre fine alla vita degli uomini. Belle, vero?", "." },
  ["aca86a9c73e3e00a"] = { "Qual è la tua funzione?", "." },
  ["acab815f4ec6a93e"] = { "Il nostro destino è la rovina di chiunque affronti il Grande Fuoco.", "." },
  ["acb53eb3a1e20b2b"] = { "Ti spacco quella brutta testa a calci!", "." },
  ["acb7a01622ddf642"] = { "Ignoro l'insulto in silenzio. Non lo dirò al mio signore, perché devo garantire la pace a ogni costo. È solo un insulto, non una dichiarazione di guerra.", "." },
  ["acb9180063d86905"] = { "So chi sei, {name}. Il destino e forze che vanno oltre ti hanno portato da me per un motivo, e non mi fa alcun piacere farne parte. Nei tempi che verranno prenderai molte decisioni, e spero che tu abbia la saggezza di prendere quelle giuste.\n\nCredimi, {race}, quando ti dico questo: le scelte giuste esistono.", "." },
  ["acbf7c7bb3682aaf"] = { "Vek'lor, sento il tuo dolore!", "." },
  ["acc9473736072e04"] = { "Sei <perdonato/perdonata>...", "." },
  ["acd1e0ef5b366d6e"] = { "Sì, {name}? Che cos'hai lì?", "." },
  ["acd2058a10381e14"] = { "Fammi vedere le bevande!", "." },
  ["ace57d9806d0dd6c"] = { "Cosa... succede a-", "." },
  ["ace709999ebe92ba"] = { "Nemico in vista! Fuoco!", "." },
  ["acea16569fc9a6d1"] = { "%s sembra ritrovare la calma ora che ha divorato i resti di {name}.", "." },
  ["acf8ae4bc70e926d"] = { "Le migliori offerte di tutta ⟦Stormwind=Roccavento⟧, amico mio, non ne troverai di migliori. Allora, come posso aiutarti?", "." },
  ["acfae3c155e15cef"] = { "Trovi ⟦Vance Undergloom=Vance Sottocupo⟧ al piano di sopra, in una stanza della ⟦Gallows' End Tavern=Taverna dell'Impiccato⟧, sul lato sud-est di Brill.", "." },
  ["acfc23662c31e685"] = { "Stai tirando troppo la corda, {name}.", "." },
})
